#include <stdio.h>

static long calls = 0;

long fib(int n) {
    calls++;
    if (n == 0 || n == 1)
        return 1;
    return fib(n - 1) + fib(n - 2);
}

int main(void) {
    long v = fib(6);

    printf("%ld %ld\n", v, calls);
    return 0;
}

#include <stdio.h>

