    int n = 16, i, j, count = 0;

    for (i = 0; i < n; i++)
        for (j = 0; j < n; j += 2)
            count++;

    printf("%d\n", count);
    return 0;
}

#include <stdio.h>

int gcd(int a, int b) {
    int t;

    while (b != 0) {
        t = a % b;
        a = b;
        b = t;
    }
    return a;
}

int main(void) {
    printf("%d %d\n", gcd(48, 18), gcd(17, 5));
    return 0;
}

