#include <stdio.h>

/* 判断 n 是否为素数（试除法，只需试到 sqrt(n)） */
int IsPrime(int n) {
    int i;

    if (n < 2)
        return 0;
    for (i = 2; i * i <= n; i++)
        if (n % i == 0)
            return 0;
    return 1;
}

int main(void) {
    int n, i, count = 0;

    if (scanf("%d", &n) != 1)
        return 1;
    for (i = 2; i <= n; i++)
        if (IsPrime(i))
            count++;
    printf("%d\n", count);
    return 0;
}

