problems.stem:
写出下列程序在给定输入下的运行结果（逐行抄写，空格与换行都要一致）。

输入：
```
4
```

程序：
```c
#include <stdio.h>

/* 统计四个程序段的语句频度（基本操作执行次数），用来实证增长阶 */
int main(void) {
    int n, i, j, k, c1 = 0, c2 = 0, c3 = 0, c4 = 0;
    if (scanf("%d", &n) != 1 || n < 1) {
        printf("输入有误\n");
        return 0;
    }
    for (i = 1; i <= n; i++) c1++;
    for (i = 1; i <= n; i++)
        for (j = 1; j <= n; j++) c2++;
    for (i = 1; i <= n; i++)
        for (j = 1; j <= i; j++) c3++;
    k = 1;
    while (k <= n) { c4++; k *= 2; }
    printf("n=%d\n", n);
    printf("单层循环=%d\n", c1);
    printf("双层嵌套=%d\n", c2);
    printf("内层依赖外层=%d\n", c3);
    printf("每轮翻倍=%d\n", c4);
    printf("c2==n*n ? %d\n", c2 == n * n);
    printf("c3==n*(n+1)/2 ? %d\n", c3 == n * (n + 1) / 2);
    printf("c2-c3==c3-c1 ? %d\n", c2 - c3 == c3 - c1);
    return 0;
}

```

