problems.stem:
写出下列程序在给定输入下的运行结果（逐行抄写，空格与换行都要一致）。

输入：
```
3
```

程序：
```c
#include <stdio.h>
#define MAXQ 5

typedef struct { int data[MAXQ]; int front, rear, size; } Queue;

/* ADT 的「运算」层：调用方只用这五个函数，不碰 data/front/rear */
static void qInit(Queue *q) { q->front = 0; q->rear = 0; q->size = 0; }
static int qEmpty(const Queue *q) { return q->size == 0; }
static int qFull(const Queue *q) { return q->size == MAXQ; }
static int qEnqueue(Queue *q, int x) {
    if (qFull(q)) return 0;
    q->data[q->rear] = x;
    q->rear = (q->rear + 1) % MAXQ;
    q->size++;
    return 1;
}
static int qDequeue(Queue *q, int *x) {
    if (qEmpty(q)) return 0;
    *x = q->data[q->front];
    q->front = (q->front + 1) % MAXQ;
    q->size--;
    return 1;
}

int main(void) {
    Queue q;
    int n, i, x, ok, out = 0;
    qInit(&q);
    if (scanf("%d", &n) != 1 || n < 0) { printf("输入有误\n"); return 0; }
    for (i = 1; i <= n; i++) {
        ok = qEnqueue(&q, i * 10);
        printf("入队 %d：%s（当前元素个数 %d）\n", i * 10, ok ? "成功" : "队满失败", q.size);
    }
    while (qDequeue(&q, &x)) { out++; printf("出队 %d\n", x); }
    printf("共出队 %d 个，队列现在为空 ? %d\n", out, qEmpty(&q));
    return 0;
}

